import {coordinateProfile,hasCoordinateGrid} from './coordinates.js?v=43';
import {themeFor,paths,coreParams,usableParams} from './learning.js?v=17';
import {curriculumMeta,interactionTags} from './curriculum.js?v=39';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function homeMarkup(experiments,prefs,{search,grade,topic,filter,pathFilter},icon){
 const topics=[...new Set(experiments.map(e=>e.topic))];
 const done=Object.values(prefs.progress||{}).filter(p=>p?.every(Boolean)).length;
 const recent=(prefs.recent||[]).map(id=>experiments.find(e=>e.id===id)).find(Boolean);
 const resume=recent||experiments.find(e=>e.id==='uniform');
 return `<div class="home-screen">
 <section class="main-banner orbital-banner cinematic-banner" aria-labelledby="bannerTitle">
  <div class="banner-art"><img class="cinematic-poster" src="video/black-hole.webp" width="1920" height="1080" alt="" aria-hidden="true" fetchpriority="high"><div id="bannerCanvas" class="banner-viewport"><span class="banner-loading" role="status">Đang mở không gian…</span></div></div>
  <div class="banner-copy"><h1 tabindex="-1" id="bannerTitle" class="primary-heading">Thí nghiệm<br><em>Vật Lí</em></h1><div class="banner-actions"><a class="button primary" href="#library">Chọn thí nghiệm ${icon('arrow-up-right')}</a><a class="banner-resume" href="#lab/${resume.id}">${recent?'Tiếp tục bài gần nhất':'Bắt đầu khảo sát'} ${icon('arrow-right')}</a></div></div>
  <button data-action="banner-fullscreen" class="banner-expand" aria-label="Xem banner toàn màn hình" title="Toàn màn hình">${icon('expand')}</button>
 </section>
 <div class="home">
 <div class="banner-model-links" aria-label="Mở nhanh thí nghiệm"><span>Thí nghiệm gợi ý</span><a href="#lab/pendulum">Con lắc <span aria-hidden="true">↗</span></a><a href="#lab/ohm">Mạch điện <span aria-hidden="true">↗</span></a><a href="#lab/prism">Lăng kính <span aria-hidden="true">↗</span></a></div>
 <section class="entry-grid" aria-label="Lựa chọn nhanh"><div class="start-here"><h2>Chọn lớp học</h2><div class="class-entry">${[10,11,12].map((g,i)=>`<button data-grade="${g}" data-goto-library="true" style="--entry-color:${['#245acb','#247b65','#7952a8'][i]}"><span>Lớp <strong>${g}</strong></span><small>${['Cơ học & năng lượng','Điện trường & sóng','Điện từ & vật lí hiện đại'][i]}</small><b aria-hidden="true">${icon('arrow-right')}</b></button>`).join('')}</div></div><div class="continue-entry"><div class="entry-heading"><h2>Bài gần nhất</h2><button data-action="progress" aria-label="Xem sổ tiến độ${done?`, ${done} bài đã khảo sát`:''}">Tiến độ ↗</button></div><a class="recent-entry" href="#lab/${resume.id}"><span aria-hidden="true">${icon('reset')}</span><div><b>${esc(resume.shortTitle)}</b><small>Lớp ${resume.grade} · ${esc(resume.topic)}</small></div><b aria-hidden="true">→</b></a></div></section>
 <section class="home-books" aria-labelledby="homeBooksTitle"><div class="home-books-heading"><h2 id="homeBooksTitle">Sách giáo khoa</h2><a href="books.html">Xem tất cả ↗</a></div><div class="home-book-list">${[10,11,12].map(g=>`<a href="books.html?grade=${g}" class="home-book"><img src="books/${g}/cover.webp" alt="Bìa Vật lí ${g}" width="85" height="120" loading="lazy"><span><strong>Vật lí ${g}</strong><small>Kết nối tri thức</small></span><span aria-hidden="true">↗</span></a>`).join('')}</div></section>
 <section id="library" aria-labelledby="libraryTitle">
 <div class="library-heading"><h2 id="libraryTitle" class="primary-heading">Thư viện thí nghiệm <span>${experiments.length}</span></h2><div class="search">${icon('search')}<label class="sr-only" for="search">Tìm thí nghiệm</label><input id="search" type="search" placeholder="Tìm hiện tượng, dụng cụ, chủ đề…" value="${esc(search)}" aria-describedby="searchHint"><button data-action="clear-search" class="search-clear" aria-label="Xóa từ khóa" hidden>×</button><kbd id="searchHint" title="Phím tắt tìm kiếm">/</kbd></div></div>
 <div class="topic-chips" aria-label="Chủ đề"><button data-topic="all" class="${topic==='all'?'selected':''}" aria-pressed="${topic==='all'}">Tất cả chủ đề</button>${topics.map(t=>{const c=themeFor({topic:t});return `<button data-topic="${t}" style="--accent:${c.color};--soft:${c.soft}" class="${t===topic?'selected':''}" aria-pressed="${t===topic}"><i aria-hidden="true"></i>${t}</button>`}).join('')}</div>
 <div class="catalog-toolbar"><div class="filters"><div class="grade-filters">${['all',10,11,12].map(g=>`<button data-grade="${g}" class="${String(g)===String(grade)?'selected':''}" aria-pressed="${String(g)===String(grade)}">${g==='all'?'Mọi lớp':`Lớp ${g}`}</button>`).join('')}</div><button class="favorite-filter ${filter==='favorites'?'selected':''}" data-action="favorites-home">${icon('star')}Đã lưu</button><button data-action="recent-home" class="${filter==='recent'?'selected':''}">Gần đây</button></div><div class="catalog-options"><label class="curriculum-picker"><span>Chủ đề SGK</span><select id="curriculumTopicFilter" aria-label="Lọc theo mạch kiến thức SGK"><option value="all">Tất cả mạch kiến thức</option></select></label><label><span class="sr-only">Mức độ</span><select id="levelFilter" aria-label="Mức độ"><option value="all">Mọi mức độ</option><option value="core">Nền tảng THPT</option><option value="extra">Mở rộng</option></select></label><label><span class="sr-only">Sắp xếp</span><select id="catalogSort" aria-label="Sắp xếp"><option value="default">Theo lộ trình</option><option value="name">Tên A → Z</option><option value="grade">Theo lớp</option></select></label></div></div>
 <div id="activeFilters" class="active-filters" aria-label="Bộ lọc đang dùng" hidden></div><div class="catalog-results"><span id="resultCount" role="status" aria-live="polite" aria-atomic="true"></span><button data-action="clear-filters" class="quiet-button" hidden>Bỏ lọc</button></div><div id="cards" class="cards"></div><nav id="pagination" class="pagination" aria-label="Trang thí nghiệm"></nav></section>
 <details class="path-section library-extra"><summary>Tuyến khảo sát <span>Học theo một mạch kiến thức</span></summary><div class="paths">${paths.map((p,i)=>`<button data-path="${i}" class="path-card ${pathFilter===i?'selected':''}" style="--path-color:${p.color}"><span class="path-icon" aria-hidden="true">${p.icon}</span><span><b>${p.title}</b><small>${p.ids.length} thí nghiệm</small></span><span aria-hidden="true">↗</span></button>`).join('')}</div></details></div></div>`;
}
export function cardsMarkup(list,prefs,icon){return list.length?list.map(e=>{
 const c=themeFor(e),meta=curriculumMeta(e),tags=interactionTags(e),done=prefs.progress?.[e.id]?.every(Boolean);
 return `<article class="experiment-card" style="--accent:${c.color};--soft:${c.soft}">
 <a href="#lab/${e.id}" class="card-image" data-thumb="${e.id}" aria-label="Xem mô hình ${esc(e.shortTitle)}">
  <div class="thumb-placeholder"><span class="thumb-subject">${esc(e.topic)}</span><span class="thumb-mark" aria-hidden="true">${c.icon}</span><b class="thumb-title">${esc(e.shortTitle)}</b></div>
 </a>
 <span class="grade-tag">Lớp ${e.grade}${e.extra?' · Mở rộng':' · Nền tảng'}</span>
 <button class="favorite-button ${prefs.favorites.includes(e.id)?'on':''}" data-favorite="${e.id}" aria-pressed="${prefs.favorites.includes(e.id)}" aria-label="Lưu ${esc(e.shortTitle)}">${icon('star')}</button>
 <a href="#lab/${e.id}" class="card-body">
  <span class="card-topic">${esc(e.topic)}</span>
  <h3>${esc(e.shortTitle.toLocaleUpperCase('vi-VN'))}</h3>
  <p class="card-purpose">${esc(e.description.split(/(?<=[.!?])\s/)[0])}</p>
  <span class="card-syllabus" title="Phân loại theo mạch kiến thức của Chương trình GDPT 2018; chưa phải số bài cụ thể trong SGK">${esc(meta.label)} <small>· ${esc(meta.scope)}</small></span>
  <span class="card-interactions" aria-label="Hình thức tương tác">${tags.map(t=>`<span class="interaction-tag">${esc(t)}</span>`).join('')}</span>
  ${done?'<span class="card-complete">✓ Đã khảo sát</span>':''}
 </a>
 <div class="card-actions"><a class="card-open" href="#lab/${e.id}" aria-label="Mở ${esc(e.shortTitle)}">Mở thí nghiệm ${icon('arrow-up-right')}</a><button class="preview-button" data-preview="${e.id}" aria-label="Xem trước ${esc(e.shortTitle)}">Xem trước</button></div>
 </article>`}).join(''):'<div class="empty"><b>Chưa tìm thấy thí nghiệm phù hợp.</b><button class="button secondary" data-action="clear-filters">Xem tất cả</button></div>';}
export function labMarkup(e,{prefs,state,config,controls,panel,mode,staticMode,experiments=[]},icon){
 const c=themeFor(e),param=coreParams(e)[0];
 return `<div class="lab" data-layout="${mode}" style="--accent:${c.color};--soft:${c.soft}"><div class="lab-breadcrumb"><a class="back" href="#library">← Thư viện</a><span class="lab-topic">${esc(e.topic)}</span><label class="lab-selector">Đổi thí nghiệm<select id="labSelect" aria-label="Chọn thí nghiệm">${experiments.map(q=>`<option value="${q.id}" ${q.id===e.id?'selected':''}>${esc(q.shortTitle)}</option>`).join('')}</select></label></div><div class="lab-heading"><div><span class="eyebrow">Lớp ${e.grade}${e.extra?' · Mở rộng':''}</span><h1 tabindex="-1" id="lessonTitle" class="primary-heading">${esc(e.shortTitle.toLocaleUpperCase('vi-VN'))}<span class="lesson-icon">${c.icon}</span></h1></div><div class="lab-header-actions"><button class="icon-button ${prefs.favorites.includes(e.id)?'on':''}" data-favorite="${e.id}" aria-label="Lưu thí nghiệm" aria-pressed="${prefs.favorites.includes(e.id)}">${icon('star')}</button><button class="button secondary" data-action="save-session">Lưu phiên ↓</button><button class="icon-button" data-action="reset" aria-label="Đặt lại mô hình; giữ bảng đo">${icon('reset')}</button><button class="icon-button" data-action="focus" aria-label="Bật hoặc tắt chế độ tập trung">${icon('expand')}</button></div></div><div class="lab-intro"><p>${esc(e.description.split(/(?<=[.!?])\s/)[0])}</p><div class="mode-switch"><button data-mode="explore" class="${mode==='explore'?'selected':''}" aria-pressed="${mode==='explore'}">Khám phá</button><button data-mode="measure" class="${mode==='measure'?'selected':''}" aria-pressed="${mode==='measure'}">Phân tích</button><button data-mode="present" class="${mode==='present'?'selected':''}" aria-pressed="${mode==='present'}">Trình chiếu</button></div></div><div class="workspace-toolbar"><div><button data-action="toggle-controls" aria-controls="controlsPanel" aria-expanded="true">${icon('sliders')}Thông số</button><button data-action="toggle-dock" aria-controls="researchPanel" aria-expanded="true">${icon('table')}Dữ liệu & ghi chép <span data-measurement-count class="measurement-count" aria-hidden="true">0</span></button><button data-action="toggle-guidance" aria-controls="guidePanel" aria-pressed="true">${icon('info')}Hướng dẫn</button></div><div><button data-action="restore-layout">Khôi phục bố cục</button><button data-action="speak-intro" class="present-narration">Nghe hướng dẫn</button><button data-action="exit-present" class="exit-present">← Thoát trình chiếu</button></div></div>${e.id==='electric'?'<div id="electricModeBar" class="electric-modes"></div>':''}
 <div class="workspace"><div class="experiment-work"><div class="instrument-zone"><section class="stage-shell"><div class="stage-top"><span class="live-tag"><i></i><span id="runStatus" role="status">Sẵn sàng</span></span><div class="stage-tools"><div class="projection-switch" role="group" aria-label="Cách biểu diễn mô hình"><button data-projection="3d" aria-pressed="${config.viewMode!=='2d'}" class="${config.viewMode!=='2d'?'selected':''}">3D</button><button data-projection="2d" aria-pressed="${config.viewMode==='2d'}" class="${config.viewMode==='2d'?'selected':''}" title="Hình chiếu vuông góc; giữ nguyên thông số và độ sâu của mô hình">2D</button></div><button data-action="toggle-axes" class="axis-toggle" aria-describedby="coordinateLegend" aria-pressed="${config.switches.axes!==false}" ${coordinateProfile(e.id,state)?'':'hidden'} title="${esc(coordinateProfile(e.id,state)?.note||'')}">${icon('axes')} Trục</button><button data-action="toggle-grid" class="grid-toggle" aria-pressed="${config.switches.grid!==false}" ${hasCoordinateGrid(coordinateProfile(e.id,state))?'':'hidden'} title="Bật hoặc tắt lưới của hệ trục">${icon('grid')} Lưới</button><button data-action="toggle-renderer" title="Đổi chất lượng đồ họa; giữ nguyên góc nhìn 2D hoặc 3D">Đồ họa nhẹ</button><button class="icon-button" data-action="png" aria-label="Tải ảnh mô hình">${icon('camera')}</button><button class="icon-button" data-action="fullscreen" aria-label="Toàn màn hình">${icon('expand')}</button></div></div><div id="rendererNotice" class="renderer-notice" hidden></div><div class="stage-viewport"><div id="visual" class="visual"><div class="render-fallback" role="status">Đang dựng mô hình…</div></div><div id="sceneTooltip" class="scene-tooltip" hidden></div><button class="touch-interaction" data-action="touch-interaction" aria-pressed="false">Bật tương tác 3D</button><span class="viewport-caption sr-only">Kéo nền để xoay · Kéo điểm màu để điều chỉnh</span></div><div class="space-controls" role="group" aria-label="Không gian mô phỏng"><button data-action="space-view" title="Xem miền làm việc rộng gấp 10 lần">Không gian ×10</button><button data-action="fit-view">Vừa mô hình</button><button data-action="zoom-out" aria-label="Thu nhỏ mô hình">−</button><button data-action="zoom-in" aria-label="Phóng to mô hình">+</button></div><div id="coordinateLegend" class="coordinate-legend" hidden></div><div id="modelStatus" class="model-status" role="status" aria-live="polite"></div><div id="readouts" class="readouts"></div><div class="transport"><button id="play" data-action="play" class="button primary" >${icon('play')}${e.visualOnly?'Phát tia':'Chạy'}</button><button class="icon-button" data-action="step"  aria-label="Tiến một bước">${icon('step')}</button><span id="activityLabel" class="activity-caption" hidden></span><div class="time-slider" ><input type="range" id="time" min="0" max="10" step=".01" value="${state.t||0}"  aria-label="Thời điểm thí nghiệm"><output id="timeValue"></output></div><select id="speed" aria-label="Tốc độ chạy" ><option value=".25">0,25×</option><option value=".5">0,5×</option><option value="1" selected>1×</option><option value="2">2×</option></select><button class="icon-button loop-toggle" data-action="loop" aria-pressed="${!!config.loop}" aria-label="Bật hoặc tắt lặp lại thí nghiệm" >${icon('loop')}</button><button class="button secondary parameters-shortcut" data-action="open-parameters">${icon('sliders')}Thông số</button><button class="button accent" data-action="record">${icon('plus')}Ghi điểm</button><button class="icon-button" data-action="reset" aria-label="Đặt lại mô hình" title="Đặt lại mô hình; giữ bảng đo">${icon('reset')}</button><button class="icon-button" data-action="toggle-guidance" aria-label="Bật hoặc tắt hướng dẫn" aria-pressed="true">${icon('info')}</button></div><div class="direct-tools"><span class="direct-mark">↔</span><label for="dragKey">Biến tương tác</label><select id="dragKey" aria-label="Thông số điều chỉnh trực tiếp">${usableParams(e,config).map(p=>`<option value="${p.key}" ${(config.dragKey||param?.key)===p.key?'selected':''}>${p.label}</option>`).join('')}</select><button data-action="param-minus" aria-label="Giảm thông số đã chọn">${icon('minus')}</button><output id="directValue"></output><button data-action="param-plus" aria-label="Tăng thông số đã chọn">${icon('plus')}</button><button data-action="locate-parameter" class="locate-parameter" aria-label="Mở ô nhập số của biến tương tác">Nhập số ↗</button></div></section><div class="experiment-tools"><button data-action="speak-intro" class="listen-quick">${icon('voice')}Nghe hướng dẫn</button><button data-action="share">↗ Thiết lập</button></div><div class="speech-mini" id="speechMini" hidden><output id="speechMiniStatus" role="status" aria-live="polite"></output><button data-action="speech-pause">Tạm dừng</button><button data-action="speech-stop">Dừng đọc</button></div><details class="guide-disclosure" id="guidePanel"><summary>Hướng dẫn & giọng đọc </summary><div class="guide-content"><div class="voice-bar"><button class="listen-guide" data-action="speak-intro">Nghe hướng dẫn</button><button data-action="speak-values">${icon('voice')}Đọc số đo</button><button data-action="speech-pause">Tạm dừng</button><button data-action="speech-stop">Dừng đọc</button>${e.id==='sound'?'<button data-action="tone" id="toneButton">♪ Nghe âm</button>':''}<button data-action="voice-settings" class="voice-settings">Giọng đọc ⚙</button></div><output id="voiceState" class="voice-state" role="status">Hoài My · Tiếng Việt tích hợp</output><div id="coach">${coachMarkup(e,config.guideStep||0)}</div></div></details><div id="selectedState" class="selected-state" hidden></div><div class="model-footnote"><button data-action="info">Điều kiện mô hình ↗</button></div></div>
 <aside class="research-dock" id="researchPanel" aria-label="Phân tích và ghi chép"><div class="dock-title"><h2>Dữ liệu & ghi chép</h2><button data-action="expand-data" aria-pressed="${!!prefs.layout.dataExpanded}">${prefs.layout.dataExpanded?'Thu chiều rộng':'Mở rộng số liệu'}</button><button data-action="toggle-dock" aria-label="Thu gọn bảng khảo sát">×</button></div><div class="work-tabs">${[['data','Dữ liệu'],['discover','Đề bài'],['tasks','Sổ tay'],['theory','Mô hình'],['sources','Nguồn']].map(([p,t])=>`<button data-panel="${p}" class="${p===panel?'selected':''}" aria-pressed="${p===panel}">${t}</button>`).join('')}</div><div id="panel"></div></aside></div><div class="resize-handle controls-resizer" role="separator" tabindex="0" data-resize="controlsWidth" aria-orientation="vertical" aria-label="Độ rộng bảng thông số"></div><aside class="controls" id="controlsPanel" aria-label="Thiết lập thí nghiệm">${controls}</aside></div><div class="lab-navigation"><button data-action="previous-lab">← Thí nghiệm trước</button><button data-action="next-lab">Thí nghiệm tiếp theo →</button></div></div>`;
}
export function discoveryMarkup(e,prefs,stored){const p=prefs.progress?.[e.id]||[false,false,false];return `<section class="discovery-panel"><div class="discovery-prompt"><span class="eyebrow">CÂU HỎI KHẢO SÁT</span><h2>${e.tasks[0]}</h2><label for="prediction">Giả thuyết của bạn</label><input id="prediction" data-notes-for="${e.id}" placeholder="Một dự đoán có thể kiểm tra…" value="${esc(stored?.prediction||'')}"><button class="button secondary" data-action="speak-task">▶ Nghe gợi ý</button></div><div class="investigation-steps">${['Dự đoán','Thao tác & đo','Giải thích'].map((v,i)=>`<label><input type="checkbox" data-progress="${i}" ${p[i]?'checked':''}><span class="step-number">0${i+1}</span><span><b>${v}</b><small>${i===0?'Nêu điều bạn nghĩ sẽ xảy ra':e.tasks[i]}</small></span></label>`).join('')}<p class="progress-note">Tự đánh dấu bước đã làm · lưu trên thiết bị này</p></div></section>`;}

export function coachMarkup(e,step=0){const p=coreParams(e)[0],model=e.learning||{change:`Điều chỉnh ${p.label.toLowerCase()}; giữ các thông số còn lại.`,observe:`Theo dõi mô hình và ba số đọc. ${e.description}`,explain:(e.analysis||e.theory||e.formula).split(/(?<=[.!?])\s/)[0]};const content=[model.change,model.observe,model.explain];return `<section class="learning-coach"><div class="coach-header"><div>${['Thay đổi','Quan sát','Giải thích'].map((name,i)=>`<button data-coach="${i}" class="${step===i?'selected':''}" aria-pressed="${step===i}"><b>${i+1}</b>${name}</button>`).join('')}</div></div><p>${esc(content[step]||content[0])}</p><div class="coach-actions">${step===0?'<button data-action="coach-try">Thử một thiết lập ↗</button>':step===1?'<button data-action="coach-record">Ghi kết quả ＋</button>':'<button data-panel="tasks">Viết giải thích →</button>'}<button data-action="speak-coach">◖ Nghe gợi ý</button></div></section>`;}
